"""Guardian REST + SSE API.

POST /evaluate             action in, decision out
POST /approve/{id}         human approves an ESCALATE
POST /reject/{id}          human rejects an ESCALATE
POST /handoff/{id}         the agent stopped waiting and asked its own human
GET  /decisions            decision history, newest first
GET  /decisions/{id}       one decision
GET  /decisions/{id}/wait  long-poll until an ESCALATE is resolved
POST /decisions/{id}/result   the agent reports what the tool returned
POST /decisions/{id}/explain  generate an explanation on demand
GET  /stream               server-sent events: every decision as it changes
GET  /health               adapter modes (live / off) and thresholds
"""

from __future__ import annotations

import asyncio
import logging
from contextlib import asynccontextmanager
from dataclasses import asdict

from fastapi import FastAPI, HTTPException, Query, Request
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import StreamingResponse

from .config import Settings
from .events import sse
from .guardian import Guardian
from .models import Decision, EvaluateRequest, ResolveRequest, ResultRequest

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(name)s: %(message)s")

KEEPALIVE_S = 15


@asynccontextmanager
async def lifespan(app: FastAPI):
    settings = Settings.from_env()
    log = logging.getLogger("guardian")
    try:
        app.state.guardian = Guardian(settings)
    except RuntimeError as exc:  # e.g. JEV_API_KEY missing: nothing to decide with
        log.error("Guardian can't start: %s", exc)
        raise SystemExit(1) from exc
    log.info("adapter modes: %s", app.state.guardian.modes)
    yield
    await app.state.guardian.aclose()


app = FastAPI(title="Guardian", version="0.1.0", lifespan=lifespan)
app.add_middleware(
    CORSMiddleware,
    allow_origin_regex=r"https?://(localhost|127\.0\.0\.1)(:\d+)?",
    allow_methods=["*"],
    allow_headers=["*"],
)


def g(request: Request) -> Guardian:
    return request.app.state.guardian


def found(d: Decision | None) -> Decision:
    if d is None:
        raise HTTPException(404, "decision not found")
    return d


@app.get("/health")
def health(request: Request) -> dict:
    guardian = g(request)
    return {
        "status": "ok",
        "modes": guardian.modes,
        "thresholds": asdict(guardian.settings.thresholds),
        "llm_model": guardian.settings.llm_model,
        "jev_model": guardian.settings.jev_model,
        "jev_base_url": guardian.settings.jev_base_url or "https://api.typesafe.ai",
        "neatlogs_project": guardian.settings.neatlogs_project,
        "neatlogs_app_url": guardian.settings.neatlogs_app_url,
        "escalation_timeout_s": guardian.settings.escalation_timeout_s,
        "fast_path_tools": guardian.settings.fast_path_tools,
    }


@app.post("/evaluate")
async def evaluate(req: EvaluateRequest, request: Request) -> Decision:
    return await g(request).evaluate(req)


@app.get("/decisions")
def list_decisions(request: Request, limit: int = Query(200, ge=1, le=1000)) -> list[Decision]:
    return g(request).store.list(limit)


@app.delete("/decisions")
def clear_decisions(request: Request) -> dict:
    g(request).clear()
    return {"cleared": True}


@app.get("/decisions/{decision_id}")
def get_decision(decision_id: str, request: Request) -> Decision:
    return found(g(request).store.get(decision_id))


@app.get("/decisions/{decision_id}/wait")
async def wait_decision(decision_id: str, request: Request, timeout: float = Query(25, ge=0, le=60)) -> Decision:
    return found(await g(request).wait(decision_id, timeout))


@app.post("/approve/{decision_id}")
def approve(decision_id: str, request: Request, body: ResolveRequest | None = None) -> Decision:
    body = body or ResolveRequest()
    return found(g(request).resolve(decision_id, True, body.by, body.note))


@app.post("/reject/{decision_id}")
def reject(decision_id: str, request: Request, body: ResolveRequest | None = None) -> Decision:
    body = body or ResolveRequest()
    return found(g(request).resolve(decision_id, False, body.by, body.note))


@app.post("/handoff/{decision_id}")
def handoff(decision_id: str, request: Request, body: ResolveRequest | None = None) -> Decision:
    body = body or ResolveRequest(by="agent")
    return found(g(request).handoff(decision_id, body.by))


@app.post("/decisions/{decision_id}/result")
def report_result(decision_id: str, body: ResultRequest, request: Request) -> Decision:
    return found(g(request).report_result(decision_id, body))


@app.post("/decisions/{decision_id}/explain")
async def explain(decision_id: str, request: Request) -> Decision:
    if g(request).explainer.mode == "off":
        raise HTTPException(409, "The explainer is off. Set LLM_BASE_URL and MODAL_PROXY_TOKEN_ID/SECRET (or LLM_API_KEY).")
    return found(await g(request).explain(decision_id))


@app.post("/traces/retry")
async def retry_traces(request: Request) -> dict:
    if g(request).tracer.mode == "off":
        raise HTTPException(409, "NeatLogs is off. Set NEATLOGS_API_KEY.")
    return await g(request).retry_traces()


@app.get("/stream")
async def stream(request: Request) -> StreamingResponse:
    guardian = g(request)

    async def events():
        queue = guardian.broker.subscribe()
        try:
            yield "retry: 2000\n\n"
            yield sse("hello", {"modes": guardian.modes})
            while not await request.is_disconnected():
                try:
                    yield await asyncio.wait_for(queue.get(), KEEPALIVE_S)
                except TimeoutError:
                    yield ": keepalive\n\n"
        finally:
            guardian.broker.unsubscribe(queue)

    return StreamingResponse(
        events(),
        media_type="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )

"""The demo agent's tools. Everything happens inside demo-agent/workspace.

Safety, independent of Guardian (the sandbox must hold even if Guardian
allows something it shouldn't, or a human approves a mistake):
  - file tools resolve paths and refuse anything outside the workspace
  - run_shell executes only `ls`, `cat`, `echo` and screened Python scripts,
    one at a time; it refuses every other command (rm, curl, git, ...), and
    pipes, chaining and redirection, and says so
  - http_request makes real GET requests only; other methods are refused
"""

from __future__ import annotations

import re
import shlex
import shutil
import subprocess
import sys
from pathlib import Path

import httpx
from langchain_core.tools import tool

HERE = Path(__file__).resolve().parent
SEED = HERE / "seed"
WORKSPACE = HERE / "workspace"

UNSAFE_PYTHON = re.compile(
    r"\b(import|from)\s+(os|subprocess|shutil|pathlib|socket|ctypes|importlib|urllib|http|requests)\b|"
    r"__import__|\beval\(|\bexec\(|\.\./|\.\.\\|['\"]/|['\"][A-Za-z]:\\",
)
MAX_OUTPUT = 4000
SHELL_OPERATORS = re.compile(r"[;&|<>`]|\$\(")


def reset_workspace() -> Path:
    if WORKSPACE.exists():
        shutil.rmtree(WORKSPACE)
    shutil.copytree(SEED, WORKSPACE)
    return WORKSPACE


def _resolve(path: str) -> Path:
    root = WORKSPACE.resolve()
    target = (root / path).resolve()
    if not target.is_relative_to(root):
        raise ValueError(f"'{path}' is outside the sandbox workspace")
    return target


def _rel(p: Path) -> str:
    return p.relative_to(WORKSPACE.resolve()).as_posix() or "."


@tool
def read_file(path: str) -> str:
    """Read a text file from the project workspace. `path` is relative to the project root."""
    return _resolve(path).read_text(encoding="utf-8")[:MAX_OUTPUT]


@tool
def write_file(path: str, content: str) -> str:
    """Create or overwrite a text file in the project workspace with `content`."""
    target = _resolve(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")
    return f"wrote {len(content)} characters to {_rel(target)}"


@tool
def delete_file(path: str) -> str:
    """Delete a file from the project workspace."""
    target = _resolve(path)
    if not target.is_file():
        return f"no such file: {path}"
    target.unlink()
    return f"deleted {_rel(target)}"


@tool
def run_shell(command: str) -> str:
    """Run one shell command (ls, cat, echo, or python path/to/script.py) in the project root and return its output.
    One command per call: pipes, `;`, `&&` and redirection are refused."""
    if SHELL_OPERATORS.search(command):
        return (f"[sandbox] refused to run `{command}`: run one command at a time "
                "(no pipes, chaining or redirection).")
    try:
        argv = shlex.split(command)
    except ValueError as exc:
        return f"could not parse command: {exc}"
    if not argv:
        return ""
    name, rest = argv[0], argv[1:]
    if name == "echo":
        return " ".join(rest)
    if name == "ls":
        return _ls([a for a in rest if not a.startswith("-")] or ["."])
    if name == "cat" and rest:
        return "\n".join(_resolve(p).read_text(encoding="utf-8") for p in rest)[:MAX_OUTPUT]
    if name in ("python", "python3") and rest and rest[0].endswith(".py"):
        return _run_python(rest[0], rest[1:])
    return f"[sandbox] refused to run `{command}`: this sandbox only runs ls, cat, echo and screened Python scripts."


def _ls(paths: list[str]) -> str:
    out = []
    for path in paths:
        target = _resolve(path)
        if target.is_dir():
            entries = "\n".join(sorted(_rel(p) + ("/" if p.is_dir() else "") for p in target.iterdir()))
            out.append(f"{_rel(target)}:\n{entries}" if len(paths) > 1 else entries)
        elif target.exists():
            out.append(_rel(target))
        else:
            out.append(f"ls: cannot access '{path}': No such file or directory")
    return "\n\n".join(out)


def _run_python(script: str, args: list[str]) -> str:
    path = _resolve(script)
    if not path.is_file():
        return f"python: can't open file '{script}'"
    if UNSAFE_PYTHON.search(path.read_text(encoding="utf-8")):
        return f"[sandbox] refused to run {script}: it uses modules or paths that could reach outside the workspace."
    proc = subprocess.run(
        [sys.executable, "-I", str(path), *args],
        cwd=WORKSPACE, capture_output=True, text=True, timeout=20,
    )
    return (proc.stdout + proc.stderr).strip()[:MAX_OUTPUT] or f"(exit code {proc.returncode})"


@tool
def http_request(url: str, method: str = "GET", body: str = "") -> str:
    """Send an HTTP request and return the status and response body."""
    if method.upper() != "GET":
        return f"[sandbox] refused to send {method.upper()} {url}: this sandbox only sends GET requests."
    try:
        resp = httpx.get(url, timeout=10, follow_redirects=True)
    except httpx.HTTPError as exc:
        return f"request failed: {exc}"
    return f"{resp.status_code}\n{resp.text[:MAX_OUTPUT]}"


TOOLS = [read_file, write_file, run_shell, delete_file, http_request]
