import re
import sys

for path in sys.argv[1:]:
    text = open(path, encoding="utf-8").read()
    body = re.sub(r"```.*?```", "", text, flags=re.S)
    for line in body.splitlines():
        stripped = re.sub(r"`[^`]*`", "", line)
        if re.search(r"(?<!\\)<[A-Za-z/]", stripped):
            print(path, "ANGLE", line[:120])
        if line.startswith("|"):
            if any("|" in s for s in re.findall(r"`[^`]*`", line)):
                print(path, "PIPE-IN-CODE", line[:120])
    heads = set()
    for h in re.findall(r"^#{1,6} (.+)$", body, flags=re.M):
        heads.add(re.sub(r"[^\w\- ]", "", h.lower()).replace(" ", "-"))
    for a in re.findall(r"\]\(#([^)]+)\)", text):
        if a not in heads:
            print(path, "BAD ANCHOR", a)
    for link in re.findall(r"\]\((\.\./[^)#]+|[A-Za-z][^):#]*\.md)\)", text):
        import os
        target = os.path.normpath(os.path.join(os.path.dirname(path), link))
        if not os.path.exists(target):
            print(path, "MISSING LINK", link)
print("done")
